insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','user','My kitchen sink is clogged, can someone come out?','My kitchen sink is clogged, can someone come out?',null,null,null,'book',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','assistant','I can help! You''re in Forest Hills (we serve Queens). Drain clearing starts at $150. I have Wed 9am or Thu 1pm with Dave — which works?','My kitchen sink is clogged, can someone come out?','I can help! You''re in Forest Hills (we serve Queens). Drain clearing starts at $150. I have Wed 9am or Thu 1pm with Dave — which works?','services#drain, service_areas#serve:Queens, service_pricing#drain_clearing, check_availability','Drain is offered; Forest Hills is served; offered real slots from availability; awaiting confirm before booking.','book','new_booking','[{"tool":"check_service_offered","service":"drain"},{"tool":"validate_service_area","region":"Queens"},{"tool":"get_service_pricing","service":"drain"},{"tool":"check_availability"}]'::jsonb, now() + interval '10 seconds'),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','user','Wednesday 9am works','Wednesday 9am works',null,null,null,'book',null,null, now() + interval '20 seconds'),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000001','assistant','You''re booked: drain clearing, Wed 9–11am with Dave at 112-20 72nd Ave. Price starts at $150, final after inspection. See you then!','Wednesday 9am works','You''re booked: drain clearing, Wed 9–11am with Dave at 112-20 72nd Ave. Price starts at $150, final after inspection. See you then!','create_appointment, check_availability','Read back + customer confirmed; re-checked availability; created appointment.','book','new_booking','[{"tool":"check_availability"},{"tool":"create_appointment","price":180}]'::jsonb, now() + interval '30 seconds');
