insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000005','user','I''d like to set up seasonal boiler maintenance twice a year. UWS.','I''d like to set up seasonal boiler maintenance twice a year. UWS.',null,null,null,'book',null,null, now()),
