('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000005','user','Monday 9am is perfect','Monday 9am is perfect',null,null,null,'book',null,null, now() + interval '20 seconds'),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000005','assistant','Booked: boiler maintenance, Mon 9–11am with Luis at 210 W 89th St, set to recur seasonally. Our office will confirm your plan. Thanks, Aisha!','Monday 9am is perfect','Booked: boiler maintenance, Mon 9–11am with Luis at 210 W 89th St, set to recur seasonally. Our office will confirm your plan. Thanks, Aisha!','create_appointment#recurrence:seasonal','Created appointment with recurrence=seasonal; lead already logged.','book','new_booking','[{"tool":"create_appointment","price":350,"recurrence":"seasonal"}]'::jsonb, now() + interval '30 seconds');
