('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000007','user','8am works, thank you','8am works, thank you',null,null,null,'book',null,null, now() + interval '20 seconds'),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000007','assistant','Booked: disposal repair, tomorrow 8–10am with Sam at 184 Bedford Ave. Starts at $150. Have a good night!','8am works, thank you','Booked: disposal repair, tomorrow 8–10am with Sam at 184 Bedford Ave. Starts at $150. Have a good night!','create_appointment','Confirmed next-day slot; created appointment.','book','new_booking','[{"tool":"create_appointment","price":175}]'::jsonb, now() + interval '30 seconds');
