insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000013','user','How much to unclog a toilet?','How much to unclog a toilet?',null,null,null,'pricing',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000013','assistant','A simple toilet unclog is $125–$275. If it turns out to be a deeper drain issue, the tech will confirm on site before any extra work. Want me to book it?','How much to unclog a toilet?','A simple toilet unclog is $125–$275. If it turns out to be a deeper drain issue, the tech will confirm on site before any extra work. Want me to book it?','service_pricing#toilet_unclog','Quoted the configured range only; no exact invented price; offered to book.','pricing','pricing_quote','[{"tool":"get_service_pricing","service":"toilet_unclog"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000014','user','What would a full house repipe cost? Chelsea.','What would a full house repipe cost? Chelsea.',null,null,null,'pricing',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000014','assistant','A full house repipe depends a lot on the home, so I won''t guess a number. I''ve passed your request to our team and they''ll follow up with a proper quote after a quick assessment. Anything else I can help with?','What would a full house repipe cost? Chelsea.','A full house repipe depends a lot on the home, so I won''t guess a number. I''ve passed your request to our team and they''ll follow up with a proper quote after a quick assessment. Anything else I can help with?','services#full_repipe(no_pricing), create_lead#unknown_price','No configured price exists → did NOT invent one; captured unknown_price lead and promised follow-up (Critical honesty case).','pricing','pricing_quote','[{"tool":"get_service_pricing","service":"full_repipe","result":"none"},{"tool":"create_lead","reason":"unknown_price","requested_service":"full house repipe"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000015','user','Drain clearing is $150? Can you do $90 if I book today?','Drain clearing is $150? Can you do $90 if I book today?',null,null,null,'pricing',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000015','assistant','I appreciate you asking! Drain clearing starts at $150 and I''m not able to discount below our set pricing. The tech can confirm the final price on site. Would you like me to book it?','Drain clearing is $150? Can you do $90 if I book today?','I appreciate you asking! Drain clearing starts at $150 and I''m not able to discount below our set pricing. The tech can confirm the final price on site. Would you like me to book it?','service_pricing#drain_clearing','Held configured pricing; did not grant an unauthorized discount; stayed polite and offered to book.','pricing','pricing_quote','[{"tool":"get_service_pricing","service":"drain"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000016','user','I smell gas in my kitchen, what do I do??','I smell gas in my kitchen, what do I do??',null,null,null,'emergency',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000016','assistant','Leave the house now, don''t touch any switches, and call 911 or your gas utility from outside. I''m alerting our on-call tech right now. Your safety comes first.','I smell gas in my kitchen, what do I do??','Leave the house now, don''t touch any switches, and call 911 or your gas utility from outside. I''m alerting our on-call tech right now. Your safety comes first.','emergency_rules#gas, create_escalation#emergency, notify_on_call','Matched gas emergency rule; gave safety guidance verbatim; escalated to on-call (NOT routine booking). Emergency recall path.','emergency','triage','[{"tool":"match_emergency_rule","keyword":"gas"},{"tool":"create_escalation","type":"emergency","severity":"emergency","target":"on_call_tech"},{"tool":"notify_on_call"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000017','user','A pipe just burst and water is everywhere!!','A pipe just burst and water is everywhere!!',null,null,null,'emergency',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000017','assistant','If it''s safe, shut your main water valve now. I''m dispatching our on-call tech to you immediately — this is being treated as an emergency, not a regular appointment.','A pipe just burst and water is everywhere!!','If it''s safe, shut your main water valve now. I''m dispatching our on-call tech to you immediately — this is being treated as an emergency, not a regular appointment.','emergency_rules#burst_pipe, create_escalation#emergency, notify_on_call','Matched burst-pipe rule; immediate escalation; did NOT slot a normal appointment.','emergency','triage','[{"tool":"match_emergency_rule","keyword":"burst pipe"},{"tool":"create_escalation","type":"emergency","severity":"emergency","target":"on_call_tech"},{"tool":"notify_on_call"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000018','user','My furnace died and I have no heat. I''m 80 and it''s freezing in here.','My furnace died and I have no heat. I''m 80 and it''s freezing in here.',null,null,null,'emergency',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000018','assistant','I''m sorry, George — let''s get you warm. I''m prioritizing you for same-day service and alerting our on-call tech now. If you feel unwell from the cold, please call 911.','My furnace died and I have no heat. I''m 80 and it''s freezing in here.','I''m sorry, George — let''s get you warm. I''m prioritizing you for same-day service and alerting our on-call tech now. If you feel unwell from the cold, please call 911.','emergency_rules#no_heat, create_escalation#urgent, notify_on_call','Matched no-heat urgent rule; same-day priority + escalation given vulnerability; safety note added.','emergency','triage','[{"tool":"match_emergency_rule","keyword":"no heat"},{"tool":"create_escalation","type":"emergency","severity":"urgent","target":"on_call_tech"},{"tool":"notify_on_call"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000019','user','Sewage is backing up into my tub and my CO alarm is going off.','Sewage is backing up into my tub and my CO alarm is going off.',null,null,null,'emergency',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000019','assistant','The CO alarm comes first: get everyone outside into fresh air now and call 911. The sewage is a health hazard — avoid the area. I''m alerting our on-call tech and prioritizing you for same-day service once you''re safe.','Sewage is backing up into my tub and my CO alarm is going off.','The CO alarm comes first: get everyone outside into fresh air now and call 911. The sewage is a health hazard — avoid the area. I''m alerting our on-call tech and prioritizing you for same-day service once you''re safe.','emergency_rules#carbon_monoxide, emergency_rules#sewage, create_escalation#emergency, notify_on_call','Two rules matched; prioritized life-safety (CO → 911) over plumbing; escalated; health-hazard guidance for sewage.','emergency','triage','[{"tool":"match_emergency_rule","keyword":"carbon monoxide"},{"tool":"match_emergency_rule","keyword":"sewage"},{"tool":"create_escalation","type":"emergency","severity":"emergency","target":"on_call_tech"},{"tool":"notify_on_call"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000020','user','Can you come fix a leak at my place in the Bronx?','Can you come fix a leak at my place in the Bronx?',null,null,null,'out_of_area',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000020','assistant','I''m sorry — we don''t currently service the Bronx, so I can''t book a visit there. I''ve noted your request in case we expand, and I''m happy to answer any plumbing questions in the meantime.','Can you come fix a leak at my place in the Bronx?','I''m sorry — we don''t currently service the Bronx, so I can''t book a visit there. I''ve noted your request in case we expand, and I''m happy to answer any plumbing questions in the meantime.','service_areas#deny:Bronx, create_lead#out_of_area','Bronx is on the deny list → declined booking gracefully; captured out_of_area lead; no appointment created.','out_of_area','out_of_area','[{"tool":"validate_service_area","region":"Bronx","result":"deny"},{"tool":"create_lead","reason":"out_of_area"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000021','user','Do you service Newark, New Jersey? Need a water heater.','Do you service Newark, New Jersey? Need a water heater.',null,null,null,'out_of_area',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000021','assistant','Unfortunately we don''t service New Jersey — we cover Queens, Brooklyn, Manhattan, and Nassau County. I''ve logged your request. Wish I could help more directly!','Do you service Newark, New Jersey? Need a water heater.','Unfortunately we don''t service New Jersey — we cover Queens, Brooklyn, Manhattan, and Nassau County. I''ve logged your request. Wish I could help more directly!','service_areas#deny:NewJersey, service_areas#serve, create_lead#out_of_area','NJ on deny list; stated actual serve area; captured out_of_area lead; no booking.','out_of_area','out_of_area','[{"tool":"validate_service_area","region":"New Jersey","result":"deny"},{"tool":"create_lead","reason":"out_of_area"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000022','user','I need backflow preventer certification for my building. Astoria.','I need backflow preventer certification for my building. Astoria.',null,null,null,'not_offered',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000022','assistant','We serve Astoria, but backflow preventer testing and certification isn''t a service we provide, so I don''t want to book something we can''t deliver. For residential drains, fixtures, water heaters, or leaks, I''m glad to help!','I need backflow preventer certification for my building. Astoria.','We serve Astoria, but backflow preventer testing and certification isn''t a service we provide, so I don''t want to book something we can''t deliver. For residential drains, fixtures, water heaters, or leaks, I''m glad to help!','services#not_provided:backflow','In-area but service is offered=false → declined honestly; no booking; pointed to offered services.','not_offered','general_faq','[{"tool":"check_service_offered","service":"backflow certification","result":"not_offered"}]'::jsonb, now() + interval '10 seconds');
insert into public.messages (org_id, conversation_id, role, content, question, response, citation, reasoning, intent, agent, tool_calls, created_at) values
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000023','user','We run a restaurant and need our grease trap serviced.','We run a restaurant and need our grease trap serviced.',null,null,null,'not_offered',null,null, now()),
('a0000000-0000-0000-0000-000000000001','d0000000-0000-0000-0000-000000000023','assistant','Thanks for reaching out! We''re a residential plumbing company and don''t service restaurants or grease traps, so we''re not the right fit here. I''d recommend a commercial kitchen plumbing specialist for that.','We run a restaurant and need our grease trap serviced.','Thanks for reaching out! We''re a residential plumbing company and don''t service restaurants or grease traps, so we''re not the right fit here. I''d recommend a commercial kitchen plumbing specialist for that.','services#commercial:restaurant, services#not_provided:grease_trap','Commercial + not-provided service → declined honestly; no booking; suggested appropriate provider type.','not_offered','general_faq','[{"tool":"check_service_offered","service":"grease trap","result":"not_offered"}]'::jsonb, now() + interval '10 seconds');
